<section class="container page-section">
<form method="get" class="grade-filter d-flex flex-wrap align-items-end gap-2 mb-3"><input type="hidden" name="jenjang" value="<?php echo html_escape($stage); ?>"><div><?php echo study_grade_select($kelas); ?></div><button class="btn btn-primary">Filter kelas</button></form>
	<p><a class="btn btn-outline-secondary" href="<?php echo site_url('belajar/arena'); ?>"><i class="bi bi-arrow-left me-2" aria-hidden="true"></i>Pilih permainan lain</a></p>
	<div class="page-heading arena-detail-hero"><div><p class="eyebrow">Arena Belajar</p><h1 class="h2"><?php echo html_escape($game['title']); ?></h1><p class="text-secondary"><?php echo html_escape($game['description']); ?></p><a class="btn btn-sun" href="<?php echo site_url('belajar/arena/riwayat'); ?>"><i class="bi bi-clock-history me-2" aria-hidden="true"></i>Riwayat saya</a></div><?php echo study_arena_art_tag($type); ?></div>
	<?php if ($settings['enabled'] !== '1'): ?><div class="alert alert-warning">Arena sedang dijeda. Riwayatmu tetap tersimpan.</div>
	<?php elseif ($type === 'expedition'): ?>
	<p>Jelajahi level secara berurutan, tanpa timer. Ambang babak baru <?php echo (int) $settings['expedition_pass']; ?>% benar; ketuntasan lama tidak berubah.</p>
	<div class="row g-3"><?php if (!$levels): ?><p>Belum ada level untuk kelas ini. Coba kelas lain atau lintas kelas.</p><?php endif; ?><?php foreach ($levels as $level): ?><div class="col-md-6 col-xl-4"><article class="feature-card h-100 d-flex flex-column"><?php echo study_arena_art_tag('expedition', $level['title']); ?><p class="eyebrow">Level <?php echo (int) $level['level_number']; ?> · <?php echo study_arena_stage($level['learning_stage']); ?></p><h2 class="h5"><?php echo html_escape($level['title']); ?></h2><p><?php echo $level['passed'] ? 'Sudah tuntas' : ($level['unlocked'] ? 'Siap dijelajahi' : 'Selesaikan level sebelumnya'); ?><?php if ($level['best_score'] !== NULL): ?> · hasil terbaik <?php echo (int) $level['best_score']; ?>%<?php endif; ?></p><?php if ($level['unlocked'] && $level['enabled']): ?><a class="btn btn-primary mt-auto align-self-start" href="<?php echo site_url('belajar/arena/pilih/'.$level['slug']); ?>"><?php echo $level['passed'] ? 'Mainkan kembali' : 'Jelajahi level'; ?><span class="visually-hidden"> <?php echo (int) $level['level_number']; ?></span></a><?php else: ?><p class="text-secondary mb-0"><?php echo $level['enabled'] ? 'Level belum terbuka' : 'Level dijeda pengelola'; ?></p><?php endif; ?></article></div><?php endforeach; ?></div>
	<?php else: ?>
	<form action="<?php echo study_arena_game_url($type); ?>" method="get" class="d-flex align-items-end flex-wrap gap-2 mb-4"><div><input type="hidden" name="kelas" value="<?php echo html_escape($kelas); ?>"><label class="form-label" for="arena-stage">Jenjang</label><select class="form-select" id="arena-stage" name="jenjang"><option value="">Semua jenjang</option><?php foreach (array('early_childhood', 'primary', 'secondary') as $option): ?><option value="<?php echo $option; ?>"<?php echo $stage === $option ? ' selected' : ''; ?>><?php echo study_arena_stage($option); ?></option><?php endforeach; ?></select></div><button class="btn btn-primary" type="submit">Tampilkan</button><?php if ($stage !== ''): ?><a class="btn btn-outline-secondary" href="<?php echo study_arena_game_url($type); ?>">Semua</a><?php endif; ?></form>
		<?php if ( ! $packs): ?><div class="empty-card"><h2 class="h5">Belum ada set aktif untuk pilihan ini</h2><p>Pilih jenjang lain atau kembali ke daftar permainan. Progres lama tidak dihapus.</p></div><?php else: ?>
	<p class="small text-secondary"><?php echo $total; ?> set/level · halaman <?php echo $page; ?> dari <?php echo $page_count; ?>. Jenjang merupakan panduan memilih kegiatan.</p><div class="row g-3">
			<?php foreach ($packs as $pack): $record = $progress[$pack['id']] ?? NULL; ?><div class="col-md-6 col-xl-4"><article class="feature-card h-100 d-flex flex-column"><?php echo study_arena_art_tag($type, $pack['title']); ?><p class="eyebrow"><?php echo study_arena_stage($pack['learning_stage']); ?></p><h2 class="h5"><?php echo html_escape($pack['title']); ?></h2><p class="small text-secondary"><?php echo $record ? (int) $record['completed'].' babak selesai dari '.(int) $record['attempts'].' percobaan' : 'Belum pernah dimainkan'; ?><?php if ($record && $record['best_score'] !== NULL): ?> · hasil terbaik <?php echo (int) $record['best_score']; ?>%<?php endif; ?></p><?php if ($type === 'flashcard' && isset($card_progress[$pack['id']])): $cards = $card_progress[$pack['id']]; ?><p class="small"><?php echo (int) $cards['reviewed_cards']; ?>/<?php echo (int) $cards['total_cards']; ?> kartu ditinjau · <?php echo (int) $cards['known_cards']; ?> sudah paham (refleksi diri).</p><?php endif; ?><a class="btn btn-primary mt-auto align-self-start" href="<?php echo site_url('belajar/arena/pilih/'.$pack['slug']); ?>">Pilih set<span class="visually-hidden">: <?php echo html_escape($pack['title']); ?></span></a></article></div><?php endforeach; ?></div>
	<nav class="d-flex flex-wrap gap-3 mt-4" aria-label="Halaman set permainan"><?php if ($page > 1): ?><a href="<?php echo html_escape(study_arena_game_url($type).'?'.http_build_query(array('kelas' => $kelas, 'jenjang' => $stage, 'halaman' => $page - 1))); ?>">Sebelumnya</a><?php endif; ?><?php if ($page < $page_count): ?><a href="<?php echo html_escape(study_arena_game_url($type).'?'.http_build_query(array('kelas' => $kelas, 'jenjang' => $stage, 'halaman' => $page + 1))); ?>">Berikutnya</a><?php endif; ?></nav>
	<?php endif; endif; ?>
</section>
